#include <stdio.h>
#include <stdbool.h>

static void digit_signature(int n, int count[10]) {
    for (int i = 0; i < 10; ++i) count[i] = 0;
    while (n > 0) {
        count[n % 10]++;
        n /= 10;
    }
}

static bool same_signature(const int a[10], const int b[10]) {
    for (int i = 0; i < 10; ++i) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

bool reorderedPowerOf2(int n) {
    int target[10];
    digit_signature(n, target);
    for (int power = 1; power <= 1000000000; power *= 2) {
        int current[10];
        digit_signature(power, current);
        if (same_signature(target, current)) return true;
    }
    return false;
}

int main(void) {
    int n;
    if (scanf("[%d]", &n) != 1) return 1;
    printf("%s\n", reorderedPowerOf2(n) ? "true" : "false");
    return 0;
}

