import java.io.*;
import java.util.*;

class Solution {
    private int[] digitSignature(int n) {
        int[] count = new int[10];
        while (n > 0) {
            count[n % 10]++;
            n /= 10;
        }
        return count;
    }

    private boolean same(int[] a, int[] b) {
        return Arrays.equals(a, b);
    }

    public boolean reorderedPowerOf2(int n) {
        int[] target = digitSignature(n);
        for (int power = 1; power <= 1_000_000_000; power *= 2) {
            if (same(target, digitSignature(power))) return true;
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        String inner = line.substring(1, line.length() - 1).trim();
        int n = Integer.parseInt(inner);
        System.out.println(new Solution().reorderedPowerOf2(n));
    }
}

